use log::{debug, info, warn};

use crate::context::Context;
use crate::desc_helpers::ochid_prefix_for;
use crate::jj;
use crate::jj::{current_op_id, op_restore};
use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
use crate::subcommand::SubcommandRunner;

/// Commit the working copies as a rung's pair, or a plain repo's
/// commit, with the given title and body.
#[derive(Args, Debug)]
pub struct CommitArgs {
    /// Where: a path in the workspace for `-s b`, its root or either
    /// repo, or the repo itself for `-s p` [default: the current
    /// directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Which repos, required: `b|both` makes the pair, `p|por`
    /// commits a plain repo, and `w` or `a` is refused
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = parse_repo_scope,
        required = true,
        help = format!("Which repos, required: {REPO_SCOPE_FORMS}, `w` and `a` refused")
    )]
    pub scope: RepoScope,

    /// Commit title, the Conventional Commit line
    #[arg(long, value_name = "STR", required = true)]
    pub title: String,

    /// Commit body, the problem and its solutions
    #[arg(long, value_name = "STR", required = true)]
    pub body: String,
}

/// Inputs to the commit op, flat, owned, clap-free: the repos `-s`
/// and `-R` resolved to, and the description.
#[derive(Debug)]
pub struct CommitParams {
    /// The pair, work then agent, or the one plain repo.
    pub target: Target,
    pub title: String,
    pub body: String,
}

/// What `-s` resolved to.
#[derive(Debug)]
pub enum Target {
    /// A dual workspace's two repos, work then agent.
    Pair { work: PathBuf, agent: PathBuf },
    /// A plain repo with no partner.
    Por(PathBuf),
}

impl TryFrom<&CommitArgs> for CommitParams {
    type Error = String;

    /// Resolve the scope into its repos, refusing a half of a dual
    /// workspace, and check the description is not blank.
    fn try_from(a: &CommitArgs) -> Result<Self, String> {
        if a.title.trim().is_empty() || a.body.trim().is_empty() {
            return Err("commit: --title and --body must both be non-empty".into());
        }
        let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
            .map_err(|e| e.to_string())?;
        let target = match &a.scope {
            RepoScope::Por => match repos.as_slice() {
                [repo] => Target::Por(repo.clone()),
                other => return Err(format!("commit -s p: expected one repo, got {}", other.len())),
            },
            RepoScope::Sides(sides) if sides.is_both() => match repos.as_slice() {
