308	    /// `-s b` makes the pair: each commit keeps its working copy's
309	    /// change id, carries the title and body, and names the other
310	    /// in its trailer, so the pair passes validate-desc in both
311	    /// directions with nothing pushed.
312	    #[test]
313	    fn both_makes_the_pair_with_trailers_naming_each_other() {
314	        let fx = Fixture::new("commit-pair");
315	        fs::write(fx.work.join("rung.txt"), "work\n").expect("write");
316	        fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write");
317	        let work_at = chid(&fx.work, "@");
318	        let agent_at = chid(&fx.bot, "@");
319	
320	        let params = CommitParams::try_from(&args("b", &fx.bot)).expect("params");
321	        commit(&mut test_ctx(), &params).expect("the pair is made");
322	
323	        assert_eq!(
324	            chid(&fx.work, "@-"),
