/// resolution verifies both repos' recorded topology agrees.
fn bot_path(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
    crate::common::require_bot_dir(workspace_root)
}

/// Restore both repos to their `jj op` snapshots. Best-effort: a
/// failed restore is warned about and never shadows the original
/// error the caller propagates.
pub(crate) fn rollback_on_failure(
    root: &Path,
    snapshots: &Snapshots,
    original: &dyn std::error::Error,
) {
    warn!("push: rolling back both repos after: {original}");
    match op_restore(root, &snapshots.work) {
        Ok(()) => info!("push: restored work repo to op {}", snapshots.work),
        Err(e) => warn!("push: work repo restore failed: {e}"),
    }
    match bot_path(root) {
        Ok(bot) => match op_restore(&bot, &snapshots.bot) {
            Ok(()) => info!("push: restored agent repo to op {}", snapshots.bot),
            Err(e) => warn!("push: agent repo restore failed: {e}"),
        },
        Err(e) => warn!("push: agent repo restore skipped (unresolvable): {e}"),
    }
}

