    let (partner, commit_journal) = match crate::pair::partner(pair, work)? {
        Partner::Committed(partner) => {
            info!(
                "push agent: fold the journal into the partner at @- {partner}, which names the \\
                 work commit, and publish {BOT_BOOKMARK}"
            );
            (partner, false)
        }
