    /// tree, description, and change id, and rebase its descendants.
    /// The trapezoid's reshape (`jj rebase -r <rev> -o <p1> -o <p2>`
    /// when the tree is already the merged one): a closing made on
    /// the last rung becomes the merge of the trunk and the ladder.
    pub fn set_parents(&mut self, rev: &str, parents: &[&str]) -> Result<()> {
        self.snapshot()?;
        let commit = self.one_commit(rev)?;
        let mut ids = Vec::with_capacity(parents.len());
        for p in parents {
            ids.push(self.one_commit(p)?.id().clone());
        }
        let mut tx = self.start_tx();
        tx.repo_mut()
            .rewrite_commit(&commit)
            .set_parents(ids)
            .write()
            .block_on()?;
        tx.repo_mut().rebase_descendants().block_on()?;
        self.finish_tx(tx, &format!("set parents of commit {}", commit.id().hex()))
    }

