//! The `reparent` subcommand: give an unpublished commit the parents
//! named, in order, keeping its own change, description, and change
//! id, so its `ochid:` trailer stays right.
//!
//! The primitive under `commit --closing`, and its inverse. A closing
//! committed on the last rung becomes the merge close-out with
//! `--onto <fork point> --onto <last rung>`, more `--onto`s give more
//! ladders, and `--onto <last rung>` alone takes it back to one
//! parent, which is how a cycle is extended after its closing.
//!
//! - The meaning is `jj rebase -r <rev> -o <p1> -o <p2> ...`: the new
//!   tree is the merge of the new parents with the commit's own diff
//!   applied, so a merge of several ladders carries every ladder's
//!   changes.
//! - `-s w` reparents in the work repo, `-s p` in a plain repo. The
//!   agent repo is a linear journal that never holds a merge, so
//!   `-s a` and `-s b` are refused.
//! - A published commit is refused, since rewriting it is a remote
//!   rewrite, as is a parent that is the commit or one of its
//!   descendants.
//! - A failure restores the repo from a `jj op` snapshot.

use std::path::PathBuf;

use clap::Args;
use log::{debug, info};

use crate::context::Context;
use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
use crate::pair::{Snapshot, is_published, refuse_conflicts, resolve_pair};
use crate::subcommand::SubcommandRunner;

/// Give a commit the parents named, keeping its change and change id.
#[derive(Args, Debug)]
pub struct ReparentArgs {
    /// The commit to reparent [default: @-]
    #[arg(value_name = "REV", default_value = "@-")]
    pub rev: String,

    /// A new parent, in order, the first the trunk side; repeat for
    /// more, or give one to make the commit linear again
    #[arg(long = "onto", short = 'o', value_name = "REV", required = true)]
    pub onto: Vec<String>,

    /// Where: a path in the workspace for `-s w`, or the repo itself
    /// for `-s p` [default: the current directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Which repo, required: `w|work` or `p|por`; the agent repo
    /// never holds a merge
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = parse_repo_scope,
        required = true,
        help = format!("Which repo, required: {REPO_SCOPE_FORMS}, `a` and `b` refused")
    )]
    pub scope: RepoScope,

    /// Print the parents it would give, and change nothing
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// Inputs to the reparent op, flat, owned, clap-free.
#[derive(Debug)]
pub struct ReparentParams {
    pub repo: PathBuf,
    pub rev: String,
    pub onto: Vec<String>,
    pub dry_run: bool,
}

impl TryFrom<&ReparentArgs> for ReparentParams {
    type Error = String;

    /// Resolve the scope to the one repo, refusing the agent side.
    fn try_from(a: &ReparentArgs) -> Result<Self, String> {
        let repo = match &a.scope {
            RepoScope::Por => {
                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
                    .map_err(|e| e.to_string())?;
                match repos.as_slice() {
                    [repo] => repo.clone(),
                    other => {
                        return Err(format!(
                            "reparent -s p: expected one repo, got {}",
                            other.len()
                        ));
                    }
                }
            }
            RepoScope::Sides(sides) if sides.is_work_only() => {
                resolve_pair(a.repo.as_deref())
                    .map_err(|e| e.to_string())?
                    .work
            }
            RepoScope::Sides(_) => {
                return Err("reparent: the agent repo is a linear journal that never holds a \
                            merge, so the scope is `-s w`, or `-s p` for a plain repo"
                    .into());
            }
        };
        Ok(ReparentParams {
            repo,
            rev: a.rev.clone(),
            onto: a.onto.clone(),
            dry_run: a.dry_run.value,
        })
    }
}

impl SubcommandRunner for ReparentArgs {
    type Params = ReparentParams;

    /// Delegate to the `TryFrom<&ReparentArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        ReparentParams::try_from(self)
    }

    /// Run the `reparent` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        reparent(ctx, params)
    }
}

/// Reparent the commit, refusing before any change a conflicted
/// repo, a published commit, and a parent at or below the commit.
pub fn reparent(
    ctx: &mut Context,
    params: &ReparentParams,
) -> Result<(), Box<dyn std::error::Error>> {
    debug!("reparent: enter {params:?}");
    let repo = &params.repo;
    let rev = &params.rev;
    refuse_conflicts(repo, "reparent", "target")?;
    if is_published(repo, rev)? {
        return Err(format!(
            "reparent: '{rev}' is published, so reparenting it is a remote rewrite. Rewrite it \
             by hand with approval, or reparent an unpublished commit"
        )
        .into());
    }
    let chid = jj::chid_of(repo, rev)?;
    let mut parents = Vec::with_capacity(params.onto.len());
    for onto in &params.onto {
        if jj::matches(repo, &format!("({onto}) & ({rev})::"))? {
            return Err(format!(
                "reparent: '{onto}' is '{rev}' or one of its descendants, so it cannot be its parent"
            )
            .into());
        }
        parents.push(jj::cid_of(repo, onto)?);
    }
    let shown: Vec<String> = parents.iter().map(|p| p[..p.len().min(12)].to_string()).collect();
    if params.dry_run {
        info!(
            "reparent: [dry-run] would give {chid} the parents {}, in {}",
            shown.join(", "),
            repo.display()
        );
        return Ok(());
    }
    let snapshot = Snapshot::take(repo)?;
    let refs: Vec<&str> = parents.iter().map(String::as_str).collect();
    match ctx.session(repo)?.reparent(rev, &refs) {
        Ok(new_id) => {
            info!(
                "reparent: {chid} has the parents {}, now commit {}",
                shown.join(", "),
                &new_id[..new_id.len().min(12)]
            );
            Ok(())
        }
        Err(e) => {
            let e: Box<dyn std::error::Error> = e.into();
            snapshot.restore("reparent", e.as_ref());
            Err(e)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_helpers::{Fixture, chid, jj_ok, test_ctx};
    use crate::{Cli, Commands};
    use clap::Parser;
    use std::fs;
    use std::path::Path;

    fn parse(args: &[&str]) -> Result<ReparentArgs, String> {
        match Cli::try_parse_from(args) {
            Ok(Cli {
                command: Some(Commands::Reparent(a)),
                ..
            }) => Ok(a),
            Ok(_) => panic!("expected Reparent"),
            Err(e) => Err(e.to_string()),
        }
    }

    fn commit_id(repo: &Path, rev: &str) -> String {
        jj_ok(repo, &["log", "-r", rev, "--no-graph", "-T", "commit_id"])
    }

    fn parents(repo: &Path, rev: &str) -> Vec<String> {
        jj_ok(
            repo,
            &["log", "-r", rev, "--no-graph", "-T", "parents.map(|p| p.commit_id()).join(\" \")"],
        )
        .split_whitespace()
        .map(str::to_string)
        .collect()
    }

    fn files(repo: &Path, rev: &str) -> String {
        jj_ok(repo, &["file", "list", "-r", rev])
    }

    fn params(fx: &Fixture, rev: &str, onto: &[&str]) -> ReparentParams {
        ReparentParams {
            repo: fx.work.clone(),
            rev: rev.to_string(),
            onto: onto.iter().map(|s| s.to_string()).collect(),
            dry_run: false,
        }
    }

    /// Write `file` and commit it with `title` on the current `@`.
    fn commit_file(repo: &Path, file: &str, title: &str) {
        fs::write(repo.join(file), file).expect("write");
        jj_ok(repo, &["commit", "-m", title]);
    }

    /// `-s` and `--onto` are required, and the agent side is refused.
    #[test]
    fn scope_and_onto_are_required_and_the_agent_side_is_refused() {
        let err = parse(&["vc-x1", "reparent", "--onto", "main"]).unwrap_err();
        assert!(err.contains("--scope"), "{err}");
        let err = parse(&["vc-x1", "reparent", "-s", "w"]).unwrap_err();
        assert!(err.contains("--onto"), "{err}");
        let fx = Fixture::new("reparent-agent");
        for scope in ["a", "b"] {
            let mut a = parse(&["vc-x1", "reparent", "-s", scope, "--onto", "main"]).unwrap();
            a.repo = Some(fx.work.clone());
            let err = ReparentParams::try_from(&a).unwrap_err();
            assert!(err.contains("linear journal"), "{scope}: {err}");
        }
    }

    /// A closing on a ladder of two rungs becomes the merge close-out
    /// and back again: two parents, the tree unchanged, the change id
    /// kept, and `--onto <last rung>` makes it linear on the rung.
    #[test]
    fn a_closing_becomes_the_merge_and_back() {
        let fx = Fixture::new("reparent-closing");
        let base = commit_id(&fx.work, "main");
        commit_file(&fx.work, "one.txt", "feat: rung one");
        commit_file(&fx.work, "two.txt", "feat: rung two");
        let tip = commit_id(&fx.work, "@-");
        commit_file(&fx.work, "closing.txt", "feat: a cycle closing");
        let id = chid(&fx.work, "@-");
        let tree = files(&fx.work, "@-");

        reparent(&mut test_ctx(), &params(&fx, "@-", &[&base, &tip])).expect("merge");
        assert_eq!(parents(&fx.work, "@-"), [base.clone(), tip.clone()]);
        assert_eq!(chid(&fx.work, "@-"), id);
        assert_eq!(files(&fx.work, "@-"), tree);

        reparent(&mut test_ctx(), &params(&fx, "@-", &[&tip])).expect("linear again");
        assert_eq!(parents(&fx.work, "@-"), [tip]);
        assert_eq!(chid(&fx.work, "@-"), id);
        assert_eq!(files(&fx.work, "@-"), tree);
    }

    /// A merge of two ladders carries both ladders' changes, the
    /// rebase meaning, where keeping the closing's own tree would
    /// silently revert the ladder it was not made on.
    #[test]
    fn a_merge_of_two_ladders_carries_both() {
        let fx = Fixture::new("reparent-two-ladders");
        let base = commit_id(&fx.work, "main");
        commit_file(&fx.work, "a.txt", "feat: ladder a");
        let a = commit_id(&fx.work, "@-");
        jj_ok(&fx.work, &["new", &base]);
        commit_file(&fx.work, "b.txt", "feat: ladder b");
        let b = commit_id(&fx.work, "@-");
        jj_ok(&fx.work, &["new", &a]);
        commit_file(&fx.work, "c.txt", "feat: closing on a");

        reparent(&mut test_ctx(), &params(&fx, "@-", &[&base, &a, &b])).expect("merge");
        assert_eq!(parents(&fx.work, "@-"), [base, a, b]);
        let tree = files(&fx.work, "@-");
        for f in ["a.txt", "b.txt", "c.txt"] {
            assert!(tree.contains(f), "{f} missing:\n{tree}");
        }
    }

    /// A published commit, and a parent at or below the commit, are
    /// refused before anything moves, and a dry run moves nothing.
    #[test]
    fn refusals_and_a_dry_run_change_nothing() {
        let fx = Fixture::new("reparent-refused");
        commit_file(&fx.work, "one.txt", "feat: rung one");
        commit_file(&fx.work, "two.txt", "feat: rung two");
        let before = parents(&fx.work, "@-");

        let err = reparent(&mut test_ctx(), &params(&fx, "@-", &["@-"])).unwrap_err();
        assert!(err.to_string().contains("descendants"), "{err}");

        let mut dry = params(&fx, "@-", &["main"]);
        dry.dry_run = true;
        reparent(&mut test_ctx(), &dry).expect("dry run");
        assert_eq!(parents(&fx.work, "@-"), before);

        let err = reparent(&mut test_ctx(), &params(&fx, "main", &["root()"])).unwrap_err();
        assert!(err.to_string().contains("published"), "{err}");
    }
}

