//! The `reparent` subcommand: give an unpublished commit the parents
//! named, in order, keeping its own change, description, and change
//! id, so its `ochid:` trailer stays right.
//!
//! The primitive under `commit --closing`, and its inverse. A closing
//! committed on the last rung becomes the merge close-out with
//! `--onto <fork point> --onto <last rung>`, more `--onto`s give more
//! ladders, and `--onto <last rung>` alone takes it back to one
//! parent, which is how a cycle is extended after its closing.
//!
//! - The meaning is `jj rebase -r <rev> -o <p1> -o <p2> ...`: the new
//!   tree is the merge of the new parents with the commit's own diff
//!   applied, so a merge of several ladders carries every ladder's
//!   changes.
//! - `-s w` reparents in the work repo, `-s p` in a plain repo. The
//!   agent repo is a linear journal that never holds a merge, so
//!   `-s a` and `-s b` are refused.
//! - A published commit is refused, since rewriting it is a remote
//!   rewrite, as is a parent that is the commit or one of its
//!   descendants.
//! - A failure restores the repo from a `jj op` snapshot.

use std::path::PathBuf;

use clap::Args;
use log::{debug, info};

use crate::context::Context;
use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
use crate::pair::{Snapshot, is_published, refuse_conflicts, resolve_pair};
use crate::subcommand::SubcommandRunner;

/// Give a commit the parents named, keeping its change and change id.
#[derive(Args, Debug)]
pub struct ReparentArgs {
    /// The commit to reparent [default: @-]
    #[arg(value_name = "REV", default_value = "@-")]
    pub rev: String,

    /// A new parent, in order, the first the trunk side; repeat for
    /// more, or give one to make the commit linear again
    #[arg(long = "onto", short = 'o', value_name = "REV", required = true)]
    pub onto: Vec<String>,

    /// Where: a path in the workspace for `-s w`, or the repo itself
    /// for `-s p` [default: the current directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Which repo, required: `w|work` or `p|por`; the agent repo
    /// never holds a merge
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = parse_repo_scope,
        required = true,
        help = format!("Which repo, required: {REPO_SCOPE_FORMS}, `a` and `b` refused")
    )]
    pub scope: RepoScope,

    /// Print the parents it would give, and change nothing
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// Inputs to the reparent op, flat, owned, clap-free.
#[derive(Debug)]
pub struct ReparentParams {
    pub repo: PathBuf,
    pub rev: String,
    pub onto: Vec<String>,
    pub dry_run: bool,
}

impl TryFrom<&ReparentArgs> for ReparentParams {
    type Error = String;

    /// Resolve the scope to the one repo, refusing the agent side.
    fn try_from(a: &ReparentArgs) -> Result<Self, String> {
        let repo = match &a.scope {
            RepoScope::Por => {
                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
                    .map_err(|e| e.to_string())?;
                match repos.as_slice() {
                    [repo] => repo.clone(),
                    other => {
                        return Err(format!(
                            "reparent -s p: expected one repo, got {}",
                            other.len()
                        ));
                    }
                }
            }
            RepoScope::Sides(sides) if sides.is_work_only() => {
                resolve_pair(a.repo.as_deref())
                    .map_err(|e| e.to_string())?
                    .work
            }
            RepoScope::Sides(_) => {
                return Err("reparent: the agent repo is a linear journal that never holds a \
                            merge, so the scope is `-s w`, or `-s p` for a plain repo"
                    .into());
            }
        };
        Ok(ReparentParams {
            repo,
            rev: a.rev.clone(),
            onto: a.onto.clone(),
            dry_run: a.dry_run.value,
        })
    }
}

impl SubcommandRunner for ReparentArgs {
    type Params = ReparentParams;

    /// Delegate to the `TryFrom<&ReparentArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        ReparentParams::try_from(self)
    }

    /// Run the `reparent` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        reparent(ctx, params)
    }
}

/// Reparent the commit, refusing before any change a conflicted
/// repo, a published commit, and a parent at or below the commit.
pub fn reparent(
    ctx: &mut Context,
    params: &ReparentParams,
) -> Result<(), Box<dyn std::error::Error>> {
    debug!("reparent: enter {params:?}");
    let repo = &params.repo;
    let rev = &params.rev;
    refuse_conflicts(repo, "reparent", "target")?;
    if is_published(repo, rev)? {
        return Err(format!(
            "reparent: '{rev}' is published, so reparenting it is a remote rewrite. Rewrite it \
             by hand with approval, or reparent an unpublished commit"
        )
        .into());
    }
    let chid = jj::chid_of(repo, rev)?;
    let mut parents = Vec::with_capacity(params.onto.len());
    for onto in &params.onto {
        if jj::matches(repo, &format!("({onto}) & ({rev})::"))? {
            return Err(format!(
                "reparent: '{onto}' is '{rev}' or one of its descendants, so it cannot be its parent"
            )
            .into());
        }
        parents.push(jj::cid_of(repo, onto)?);
    }
    let shown: Vec<String> = parents.iter().map(|p| p[..p.len().min(12)].to_string()).collect();
    if params.dry_run {
        info!(
            "reparent: [dry-run] would give {chid} the parents {}, in {}",
            shown.join(", "),
            repo.display()
        );
        return Ok(());
    }
    let snapshot = Snapshot::take(repo)?;
    let refs: Vec<&str> = parents.iter().map(String::as_str).collect();
    match ctx.session(repo)?.reparent(rev, &refs) {
        Ok(new_id) => {
            info!(
                "reparent: {chid} has the parents {}, now commit {}",
                shown.join(", "),
                &new_id[..new_id.len().min(12)]
            );
            Ok(())
        }
        Err(e) => {
            let e: Box<dyn std::error::Error> = e.into();
            snapshot.restore("reparent", e.as_ref());
            Err(e)
        }
    }
}

