/// The sources resolved to commit ids, checked against the target:
/// refusing a source at or below it, warning on one that is an
/// ancestor of another.
pub fn resolve_sources(
    repo: &Path,
    target: &str,
    from: &[String],
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut ids = Vec::with_capacity(from.len());
    for source in from {
        if jj::matches(repo, &format!("({source}) & ({target})::"))? {
            return Err(format!(
                "merge: the source '{source}' is the target '{target}' or below it, so it \
                 cannot be its parent"
            )
            .into());
        }
        ids.push(jj::cid_of(repo, source)?);
    }
    for (i, a) in ids.iter().enumerate() {
        for (j, b) in ids.iter().enumerate() {
            if i != j && a != b && jj::matches(repo, &format!("{a} & ::{b}"))? {
                warn!(
                    "merge: the source '{}' is an ancestor of the source '{}', a redundant \
                     parent",
                    from[i], from[j]
                );
            }
        }
    }
