        let err = parse(&["vc-x1", "merge", "-s", "w", "--target", "@"]).unwrap_err();
        assert!(err.contains("--from"), "{err}");
        let fx = Fixture::new("merge-agent");
        for scope in ["a", "b"] {
            let mut a = parse(&[
                "vc-x1", "merge", "-s", scope, "--target", "@", "--from", "main",
            ])
