            a.repo = Some(fx.work.clone());
            let err = MergeParams::try_from(&a).unwrap_err();
            assert!(err.contains("linear journal"), "{scope}: {err}");
        }
    }

    /// Two sources with their own changes merge into `@`: the target's
    /// parents are the sources in order, its tree carries both, and
    /// one source after makes it linear again with its change id kept.
    #[test]
    fn two_sources_merge_into_the_target_and_back() {
        let fx = Fixture::new("merge-two");
        let base = commit_id(&fx.work, "main");
        commit_file(&fx.work, "a.txt", "a", "feat: source a");
        let a = commit_id(&fx.work, "@-");
        jj_ok(&fx.work, &["new", &base]);
        commit_file(&fx.work, "b.txt", "b", "feat: source b");
        let b = commit_id(&fx.work, "@-");
        jj_ok(&fx.work, &["new", &base]);
        let id = chid(&fx.work, "@");

        merge(&mut test_ctx(), &params(&fx, "@", &[&a, &b])).expect("merge");
        assert_eq!(parents(&fx.work, "@"), [a.clone(), b]);
        let tree = files(&fx.work, "@");
        assert!(tree.contains("a.txt") && tree.contains("b.txt"), "{tree}");
        assert_eq!(chid(&fx.work, "@"), id);

        merge(&mut test_ctx(), &params(&fx, "@", &[&a])).expect("linear again");
        assert_eq!(parents(&fx.work, "@"), [a]);
        assert_eq!(chid(&fx.work, "@"), id);
    }

    /// A source with no history of its own, a root's child from an
    /// unrelated line, merges like any other.
    #[test]
    fn a_rootless_source_merges() {
        let fx = Fixture::new("merge-root");
        let main = commit_id(&fx.work, "main");
        jj_ok(&fx.work, &["new", "root()"]);
        commit_file(&fx.work, "other.txt", "other", "feat: an unrelated line");
        let other = commit_id(&fx.work, "@-");
        jj_ok(&fx.work, &["new", &main]);

        merge(&mut test_ctx(), &params(&fx, "@", &[&main, &other])).expect("merge");
        assert_eq!(parents(&fx.work, "@"), [main, other]);
        assert!(files(&fx.work, "@").contains("other.txt"));
    }

