fn has_ladder(repo: &Path) -> Result<bool, Box<dyn std::error::Error>> {
    Ok(jj::cid_of(repo, "@-")? != jj::cid_of(repo, "heads(::@- & ::main)")?)
}

/// The merge close-out's two parents, as commit ids read before the commit:
/// the fork point of the ladder and `main`, and the last rung, the
/// work `@-`. Refused when there is no ladder, the last rung being
/// the fork point itself.
fn closing_parents(repo: &Path) -> Result<(String, String), Box<dyn std::error::Error>> {
    let tip = jj::cid_of(repo, "@-")?;
    let base = jj::cid_of(repo, "heads(::@- & ::main)")?;
    if base == tip {
        return Err(
            "commit --closing: the work @- is on `main`, so there is no ladder to close. \\
                    A closing is made on the cycle's last rung"
                .into(),
        );
    }
    Ok((base, tip))
}

