    ctx: &mut Context,
    repo: &Path,
    base: &str,
    tip: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    info!("commit work: the closing merges {base} and {tip} into @");
    crate::merge::set_parents(ctx, repo, "@", &[base.to_string(), tip.to_string()], "commit")?;
    Ok(())
}''')
