1	//! The `merge` subcommand: give one target commit the sources named
2	//! as its parents, in order, keeping the target's own change,
3	//! description, and change id, so its `ochid:` trailer stays right.
4	//!
5	//! One target and N sources, with no assumption about where either
6	//! lives: the target is usually `@`, before a closing's edits are
7	//! committed, and the sources are anything, a bookmark, `main`, a
8	//! change id, a merge made earlier, a root, part of a set merged
9	//! piecemeal elsewhere.
10	//!
11	//! - The meaning is `jj rebase -r <target> -o <s1> -o <s2> ...`: the
12	//!   target's tree becomes the merge of the sources with its own
13	//!   change applied, so it carries every source's changes.
14	//! - A cycle's closing is `--target @ --from main --from @-`, which
15	//!   `commit --closing` runs before it commits, and one `--from`
16	//!   takes the target back to a single parent, the undo that lets a
17	//!   cycle be extended after its closing.
18	//! - Refused: a source that is the target or below it, a cycle, and
19	//!   a published target, a remote rewrite. Reported and allowed: a
20	//!   conflicted result, left as jj leaves it. A source that is an
21	//!   ancestor of another is the no-fast-forward shape, a closing's
22	//!   `main` below its last rung, so it is neither.
23	//! - `-s w` merges in the work repo, `-s p` in a plain repo. The
24	//!   agent repo is a linear journal that never holds a merge, so
25	//!   `-s a` and `-s b` are refused.
26	//! - A failure restores the repo from a `jj op` snapshot.
27	
28	use std::path::{Path, PathBuf};
29	
30	use clap::Args;
31	use log::{debug, info, warn};
32	
33	use crate::context::Context;
34	use crate::jj;
35	use crate::options_flags::dry_run::DryRunFlag;
36	use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
37	use crate::pair::{Snapshot, is_published, refuse_conflicts, resolve_pair};
38	use crate::subcommand::SubcommandRunner;
39	
40	/// Give a target commit the sources as its parents, keeping its
41	/// change and change id.
42	#[derive(Args, Debug)]
43	pub struct MergeArgs {
44	    /// The commit whose parents are set, typically @
45	    #[arg(long, value_name = "REV", required = true)]
46	    pub target: String,
47	
48	    /// A source, the target's parents in the order given; repeat for
49	    /// each, one making the target linear on it
50	    #[arg(long = "from", value_name = "REVSET", required = true)]
51	    pub from: Vec<String>,
52	
53	    /// Where: a path in the workspace for `-s w`, or the repo itself
54	    /// for `-s p` [default: the current directory]
55	    #[arg(short = 'R', long, value_name = "PATH")]
56	    pub repo: Option<PathBuf>,
57	
58	    /// Which repo, required: `w|work` or `p|por`; the agent repo
59	    /// never holds a merge
60	    #[arg(
61	        short = 's',
62	        long,
63	        value_name = "SCOPE",
64	        value_parser = parse_repo_scope,
65	        required = true,
66	        help = format!("Which repo, required: {REPO_SCOPE_FORMS}, `a` and `b` refused")
67	    )]
68	    pub scope: RepoScope,
69	
70	    /// Print the parents it would give, and change nothing
71	    #[command(flatten)]
72	    pub dry_run: DryRunFlag,
73	}
74	
75	/// Inputs to the merge op, flat, owned, clap-free.
76	#[derive(Debug)]
77	pub struct MergeParams {
78	    pub repo: PathBuf,
79	    pub target: String,
80	    pub from: Vec<String>,
81	    pub dry_run: bool,
82	}
83	
84	impl TryFrom<&MergeArgs> for MergeParams {
85	    type Error = String;
86	
87	    /// Resolve the scope to the one repo, refusing the agent side.
88	    fn try_from(a: &MergeArgs) -> Result<Self, String> {
89	        let repo = match &a.scope {
90	            RepoScope::Por => {
91	                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
92	                    .map_err(|e| e.to_string())?;
93	                match repos.as_slice() {
94	                    [repo] => repo.clone(),
95	                    other => {
96	                        return Err(format!(
97	                            "merge -s p: expected one repo, got {}",
98	                            other.len()
99	                        ));
100	                    }
101	                }
102	            }
103	            RepoScope::Sides(sides) if sides.is_work_only() => {
104	                resolve_pair(a.repo.as_deref())
105	                    .map_err(|e| e.to_string())?
106	                    .work
107	            }
108	            RepoScope::Sides(_) => {
109	                return Err(
110	                    "merge: the agent repo is a linear journal that never holds a \
111	                            merge, so the scope is `-s w`, or `-s p` for a plain repo"
112	                        .into(),
113	                );
114	            }
115	        };
116	        Ok(MergeParams {
117	            repo,
118	            target: a.target.clone(),
119	            from: a.from.clone(),
120	            dry_run: a.dry_run.value,
121	        })
