139	/// The sources resolved to commit ids, refusing one at or below the
140	/// target. A source that is an ancestor of another is allowed and
141	/// unremarked: it is the no-fast-forward shape, a closing's `main`
142	/// below its last rung.
143	pub fn resolve_sources(
144	    repo: &Path,
145	    target: &str,
146	    from: &[String],
147	) -> Result<Vec<String>, Box<dyn std::error::Error>> {
148	    let mut ids = Vec::with_capacity(from.len());
149	    for source in from {
150	        if jj::matches(repo, &format!("({source}) & ({target})::"))? {
151	            return Err(format!(
152	                "merge: the source '{source}' is the target '{target}' or below it, so it \
153	                 cannot be its parent"
154	            )
155	            .into());
156	        }
157	        ids.push(jj::cid_of(repo, source)?);
158	    }
