162	/// Give the target the sources' commit ids as its parents, in `repo`
163	/// under `who`, returning its new commit id and warning when the
164	/// result is conflicted. The caller has checked and snapshotted.
165	pub fn set_parents(
166	    ctx: &mut Context,
167	    repo: &Path,
168	    target: &str,
169	    sources: &[String],
170	    who: &str,
171	) -> Result<String, Box<dyn std::error::Error>> {
172	    let refs: Vec<&str> = sources.iter().map(String::as_str).collect();
173	    let new_id = ctx.session(repo)?.reparent(target, &refs)?;
174	    if jj::matches(repo, &format!("{new_id} & conflicts()"))? {
175	        warn!(
176	            "{who}: the merge is conflicted, its sources changing the same lines: `jj resolve \
177	             --list -r {}` names the paths, and resolving them, or another merge, is yours",
178	            &new_id[..new_id.len().min(12)]
179	        );
180	    }
181	    Ok(new_id)
182	}
