184	/// Merge the sources into the target, refusing before any change a
185	/// conflicted repo, a published target, and a source at or below the
186	/// target.
187	pub fn merge(ctx: &mut Context, params: &MergeParams) -> Result<(), Box<dyn std::error::Error>> {
188	    debug!("merge: enter {params:?}");
189	    let repo = &params.repo;
190	    let target = &params.target;
191	    refuse_conflicts(repo, "merge", "target's")?;
192	    if is_published(repo, target)? {
193	        return Err(format!(
194	            "merge: the target '{target}' is published, so changing its parents is a remote \
195	             rewrite. Rewrite it by hand with approval, or merge into an unpublished commit"
196	        )
197	        .into());
198	    }
199	    let chid = jj::chid_of(repo, target)?;
200	    let sources = resolve_sources(repo, target, &params.from)?;
201	    let shown: Vec<String> = sources
202	        .iter()
203	        .map(|p| p[..p.len().min(12)].to_string())
204	        .collect();
205	    if params.dry_run {
206	        info!(
207	            "merge: [dry-run] would give {chid} the parents {}, in {}",
208	            shown.join(", "),
209	            repo.display()
210	        );
211	        return Ok(());
212	    }
213	    let snapshot = Snapshot::take(repo)?;
214	    match set_parents(ctx, repo, target, &sources, "merge") {
215	        Ok(new_id) => {
216	            info!(
217	                "merge: {chid} has the parents {}, now commit {}",
218	                shown.join(", "),
219	                &new_id[..new_id.len().min(12)]
220	            );
221	            Ok(())
222	        }
223	        Err(e) => {
224	            snapshot.restore("merge", e.as_ref());
225	            Err(e)
226	        }
227	    }
228	}
