//! The `merge` subcommand: give one target commit the sources named
//! as its parents, in order, keeping the target's own change,
//! description, and change id, so its `ochid:` trailer stays right.
//!
//! One target and N sources, with no assumption about where either
//! lives: the target is usually `@`, before a closing's edits are
//! committed, and the sources are anything, a bookmark, `main`, a
//! change id, a merge made earlier, a root, part of a set merged
//! piecemeal elsewhere.
//!
//! - The meaning is `jj rebase -r <target> -o <s1> -o <s2> ...`: the
//!   target's tree becomes the merge of the sources with its own
//!   change applied, so it carries every source's changes.
//! - A cycle's closing is `--target @ --from main --from @-`, which
//!   `commit --closing` runs before it commits, and one `--from`
//!   takes the target back to a single parent, the undo that lets a
//!   cycle be extended after its closing.
//! - Refused: a source that is the target or below it, a cycle, and
//!   a published target, a remote rewrite. Reported and allowed: a
//!   conflicted result, left as jj leaves it. A source that is an
//!   ancestor of another is the no-fast-forward shape, a closing's
//!   `main` below its last rung, so it is neither.
//! - `-s w` merges in the work repo, `-s p` in a plain repo. The
//!   agent repo is a linear journal that never holds a merge, so
//!   `-s a` and `-s b` are refused.
//! - A failure restores the repo from a `jj op` snapshot.

use std::path::{Path, PathBuf};

use clap::Args;
use log::{debug, info, warn};

use crate::context::Context;
use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
use crate::pair::{Snapshot, is_published, refuse_conflicts, resolve_pair};
use crate::subcommand::SubcommandRunner;

/// Give a target commit the sources as its parents, keeping its
/// change and change id.
#[derive(Args, Debug)]
pub struct MergeArgs {
    /// The commit whose parents are set, typically @
    #[arg(long, value_name = "REV", required = true)]
    pub target: String,

    /// A source, the target's parents in the order given; repeat for
    /// each, one making the target linear on it
    #[arg(long = "from", value_name = "REVSET", required = true)]
    pub from: Vec<String>,

    /// Where: a path in the workspace for `-s w`, or the repo itself
    /// for `-s p` [default: the current directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Which repo, required: `w|work` or `p|por`; the agent repo
    /// never holds a merge
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = parse_repo_scope,
        required = true,
        help = format!("Which repo, required: {REPO_SCOPE_FORMS}, `a` and `b` refused")
    )]
    pub scope: RepoScope,

    /// Print the parents it would give, and change nothing
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// Inputs to the merge op, flat, owned, clap-free.
#[derive(Debug)]
pub struct MergeParams {
    pub repo: PathBuf,
    pub target: String,
    pub from: Vec<String>,
    pub dry_run: bool,
}

impl TryFrom<&MergeArgs> for MergeParams {
    type Error = String;

    /// Resolve the scope to the one repo, refusing the agent side.
    fn try_from(a: &MergeArgs) -> Result<Self, String> {
        let repo = match &a.scope {
            RepoScope::Por => {
                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
                    .map_err(|e| e.to_string())?;
                match repos.as_slice() {
                    [repo] => repo.clone(),
                    other => {
                        return Err(format!(
                            "merge -s p: expected one repo, got {}",
                            other.len()
                        ));
                    }
                }
            }
            RepoScope::Sides(sides) if sides.is_work_only() => {
                resolve_pair(a.repo.as_deref())
                    .map_err(|e| e.to_string())?
                    .work
            }
            RepoScope::Sides(_) => {
                return Err(
                    "merge: the agent repo is a linear journal that never holds a \
                            merge, so the scope is `-s w`, or `-s p` for a plain repo"
                        .into(),
                );
            }
        };
        Ok(MergeParams {
            repo,
            target: a.target.clone(),
            from: a.from.clone(),
            dry_run: a.dry_run.value,
        })
    }
}

impl SubcommandRunner for MergeArgs {
    type Params = MergeParams;

    /// Delegate to the `TryFrom<&MergeArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        MergeParams::try_from(self)
    }

    /// Run the `merge` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        merge(ctx, params)
    }
}

/// The sources resolved to commit ids, refusing one at or below the
/// target. A source that is an ancestor of another is allowed and
/// unremarked: it is the no-fast-forward shape, a closing's `main`
/// below its last rung.
pub fn resolve_sources(
    repo: &Path,
    target: &str,
    from: &[String],
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut ids = Vec::with_capacity(from.len());
    for source in from {
        if jj::matches(repo, &format!("({source}) & ({target})::"))? {
            return Err(format!(
                "merge: the source '{source}' is the target '{target}' or below it, so it \
                 cannot be its parent"
            )
            .into());
        }
        ids.push(jj::cid_of(repo, source)?);
    }
    Ok(ids)
}

/// Give the target the sources' commit ids as its parents, in `repo`
/// under `who`, returning its new commit id and warning when the
/// result is conflicted. The caller has checked and snapshotted.
pub fn set_parents(
    ctx: &mut Context,
    repo: &Path,
    target: &str,
    sources: &[String],
    who: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let refs: Vec<&str> = sources.iter().map(String::as_str).collect();
    let new_id = ctx.session(repo)?.reparent(target, &refs)?;
    if jj::matches(repo, &format!("{new_id} & conflicts()"))? {
        warn!(
            "{who}: the merge is conflicted, its sources changing the same lines: `jj resolve \
             --list -r {}` names the paths, and resolving them, or another merge, is yours",
            &new_id[..new_id.len().min(12)]
        );
    }
    Ok(new_id)
}

/// Merge the sources into the target, refusing before any change a
/// conflicted repo, a published target, and a source at or below the
/// target.
pub fn merge(ctx: &mut Context, params: &MergeParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("merge: enter {params:?}");
    let repo = &params.repo;
    let target = &params.target;
    refuse_conflicts(repo, "merge", "target's")?;
    if is_published(repo, target)? {
        return Err(format!(
            "merge: the target '{target}' is published, so changing its parents is a remote \
             rewrite. Rewrite it by hand with approval, or merge into an unpublished commit"
        )
        .into());
    }
    let chid = jj::chid_of(repo, target)?;
    let sources = resolve_sources(repo, target, &params.from)?;
    let shown: Vec<String> = sources
        .iter()
        .map(|p| p[..p.len().min(12)].to_string())
        .collect();
    if params.dry_run {
        info!(
            "merge: [dry-run] would give {chid} the parents {}, in {}",
            shown.join(", "),
            repo.display()
        );
        return Ok(());
    }
    let snapshot = Snapshot::take(repo)?;
    match set_parents(ctx, repo, target, &sources, "merge") {
        Ok(new_id) => {
            info!(
                "merge: {chid} has the parents {}, now commit {}",
                shown.join(", "),
                &new_id[..new_id.len().min(12)]
            );
            Ok(())
        }
        Err(e) => {
            snapshot.restore("merge", e.as_ref());
            Err(e)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_helpers::{Fixture, chid, jj_ok, test_ctx};
    use crate::{Cli, Commands};
    use clap::Parser;
    use std::fs;

    fn parse(args: &[&str]) -> Result<MergeArgs, String> {
        match Cli::try_parse_from(args) {
            Ok(Cli {
                command: Some(Commands::Merge(a)),
