use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, parse_repo_scope};
use crate::pair::resolve_pair;
use crate::subcommand::SubcommandRunner;

/// Point an existing bookmark at one commit, locally.
#[derive(Args, Debug)]
pub struct MoveBookmarkArgs {
    /// The bookmark to move, which must already exist
    #[arg(long, value_name = "NAME", required = true)]
    pub bookmark: String,

    /// Where it moves to, a revset of exactly one commit, a bookmark
    /// or a rev
    #[arg(long, value_name = "REV", required = true)]
    pub target: String,

    /// Move it backward or sideways, as `jj` allows it
    #[arg(long)]
    pub allow_backwards: bool,

    /// Where: a path in the workspace for `-s w`, or the repo itself
    /// for `-s p` [default: the current directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Which repo, required: `w|work` or `p|por`; the agent repo's
    /// `main` is push's to set
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = parse_repo_scope,
        required = true,
        help = format!("Which repo, required: {REPO_SCOPE_FORMS}, `a` and `b` refused")
    )]
    pub scope: RepoScope,

    /// Print the move it would make, and change nothing
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// Inputs to the move-bookmark op, flat, owned, clap-free.
#[derive(Debug)]
pub struct MoveBookmarkParams {
    pub repo: PathBuf,
    pub bookmark: String,
    pub target: String,
    pub allow_backwards: bool,
    pub dry_run: bool,
}

impl TryFrom<&MoveBookmarkArgs> for MoveBookmarkParams {
    type Error = String;

    /// Resolve the scope to the one repo, refusing the agent side.
    fn try_from(a: &MoveBookmarkArgs) -> Result<Self, String> {
        let repo = match &a.scope {
            RepoScope::Por => {
                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
                    .map_err(|e| e.to_string())?;
                match repos.as_slice() {
                    [repo] => repo.clone(),
                    other => {
                        return Err(format!(
                            "move-bookmark -s p: expected one repo, got {}",
                            other.len()
                        ));
                    }
                }
            }
