                     scope is `-s w`, or `-s p` for a plain repo"
                        .into(),
                );
            }
        };
        Ok(MoveBookmarkParams {
            repo,
            bookmark: a.bookmark.clone(),
            target: a.target.clone(),
            allow_backwards: a.allow_backwards,
            dry_run: a.dry_run.value,
        })
    }
}

impl SubcommandRunner for MoveBookmarkArgs {
    type Params = MoveBookmarkParams;

    /// Delegate to the `TryFrom<&MoveBookmarkArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        MoveBookmarkParams::try_from(self)
    }

    /// Run the `move-bookmark` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        move_bookmark(ctx, params)
    }
}

/// Move the bookmark to the target, refusing before any change a
/// bookmark that does not exist, a target that is not one commit, and
/// a backward or sideways move unless `--allow-backwards`.
pub fn move_bookmark(
    ctx: &mut Context,
    params: &MoveBookmarkParams,
) -> Result<(), Box<dyn std::error::Error>> {
    debug!("move-bookmark: enter {params:?}");
    let repo = &params.repo;
    let name = &params.bookmark;
    let target = &params.target;
    if !jj::local_bookmark_exists(repo, name)? {
        return Err(format!(
            "move-bookmark: the bookmark '{name}' does not exist in {}, and move-bookmark \
             creates none",
            repo.display()
        )
        .into());
    }
    let to = match jj::cids_of(repo, target)?.as_slice() {
        [one] => one.clone(),
        other => {
            return Err(format!(
                "move-bookmark: the target '{target}' names {} commits, and a bookmark points \
                 at exactly one",
                other.len()
            )
            .into());
        }
    };
    let at = format!("bookmarks(exact:{name:?})");
    let from = jj::cids_of(repo, &at)?;
    let short = |id: &str| id[..id.len().min(12)].to_string();
    let shown_from = from.iter().map(|id| short(id)).collect::<Vec<_>>().join(", ");
    if from == [to.clone()] {
        info!(
            "move-bookmark: '{name}' is already at {}, so nothing changes, in {}",
            short(&to),
            repo.display()
        );
        return Ok(());
    }
    // Forward when every commit the bookmark points at, a conflicted
    // one's included, is an ancestor of the target.
    let forward = !jj::matches(repo, &format!("{at} ~ ::{to}"))?;
    if !forward && !params.allow_backwards {
        return Err(format!(
            "move-bookmark: moving '{name}' from {shown_from} to {} is backward or sideways, \
             leaving commits off its line. Pass --allow-backwards to move it anyway",
            short(&to)
        )
        .into());
    }
    if params.dry_run {
        info!(
            "move-bookmark: [dry-run] would move '{name}' from {shown_from} to {}, in {}",
            short(&to),
            repo.display()
        );
        return Ok(());
    }
    ctx.session(repo)?.bookmark_set(name, &to)?;
    info!(
        "move-bookmark: '{name}' moved from {shown_from} to {}, locally, in {}",
        short(&to),
        repo.display()
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_helpers::{Fixture, jj_ok, test_ctx};
    use crate::{Cli, Commands};
    use clap::Parser;
    use std::fs;
    use std::path::Path;

    fn parse(args: &[&str]) -> Result<MoveBookmarkArgs, String> {
        match Cli::try_parse_from(args) {
            Ok(Cli {
                command: Some(Commands::MoveBookmark(a)),
                ..
            }) => Ok(a),
            Ok(_) => panic!("expected MoveBookmark"),
            Err(e) => Err(e.to_string()),
        }
    }

    fn commit_id(repo: &Path, rev: &str) -> String {
        jj_ok(repo, &["log", "-r", rev, "--no-graph", "-T", "commit_id"])
    }

    fn params(fx: &Fixture, bookmark: &str, target: &str) -> MoveBookmarkParams {
        MoveBookmarkParams {
            repo: fx.work.clone(),
            bookmark: bookmark.to_string(),
            target: target.to_string(),
            allow_backwards: false,
            dry_run: false,
        }
    }

    /// Write `file` and commit it with `title` on `@`.
    fn commit_file(repo: &Path, file: &str, title: &str) {
        fs::write(repo.join(file), file).expect("write");
        jj_ok(repo, &["commit", "-m", title]);
    }

    /// `-s`, `--bookmark`, and `--target` are required, and the agent
    /// side is refused.
    #[test]
    fn scope_bookmark_and_target_are_required_and_the_agent_side_is_refused() {
        let err = parse(&["vc-x1", "move-bookmark", "--bookmark", "b", "--target", "@-"])
            .unwrap_err();
        assert!(err.contains("--scope"), "{err}");
        let err = parse(&["vc-x1", "move-bookmark", "-s", "w", "--target", "@-"]).unwrap_err();
        assert!(err.contains("--bookmark"), "{err}");
        let err = parse(&["vc-x1", "move-bookmark", "-s", "w", "--bookmark", "b"]).unwrap_err();
        assert!(err.contains("--target"), "{err}");
        let fx = Fixture::new("mvbm-agent");
        for scope in ["a", "b"] {
            let mut a = parse(&[
                "vc-x1",
                "move-bookmark",
                "-s",
                scope,
                "--bookmark",
                "main",
                "--target",
                "@-",
            ])
            .unwrap();
            a.repo = Some(fx.work.clone());
            let err = MoveBookmarkParams::try_from(&a).unwrap_err();
            assert!(err.contains("push's agent half"), "{scope}: {err}");
        }
    }

    /// A bookmark moves forward along its line to a rev or to another
    /// bookmark, locally, the remote left where it was, and a move to
    /// where it is changes nothing.
    #[test]
    fn a_bookmark_moves_forward_locally() {
        let fx = Fixture::new("mvbm-forward");
        jj_ok(&fx.work, &["bookmark", "create", "line", "-r", "main"]);
        commit_file(&fx.work, "one.txt", "feat: one");
        commit_file(&fx.work, "two.txt", "feat: two");
        let one = commit_id(&fx.work, "@--");
        let two = commit_id(&fx.work, "@-");
        let remote = commit_id(&fx.work, "main@origin");

        move_bookmark(&mut test_ctx(), &params(&fx, "line", "@--")).expect("to a rev");
        assert_eq!(commit_id(&fx.work, "line"), one);
        jj_ok(&fx.work, &["bookmark", "create", "tip", "-r", &two]);
        move_bookmark(&mut test_ctx(), &params(&fx, "line", "tip")).expect("to a bookmark");
        assert_eq!(commit_id(&fx.work, "line"), two);
        move_bookmark(&mut test_ctx(), &params(&fx, "main", "line")).expect("main forward");
        assert_eq!(commit_id(&fx.work, "main"), two);
        assert_eq!(commit_id(&fx.work, "main@origin"), remote);

        move_bookmark(&mut test_ctx(), &params(&fx, "line", &two)).expect("already there");
        assert_eq!(commit_id(&fx.work, "line"), two);
    }

    /// A backward or sideways move is refused, and taken with
    /// `--allow-backwards`.
    #[test]
    fn a_backward_or_sideways_move_takes_the_flag() {
        let fx = Fixture::new("mvbm-back");
        let base = commit_id(&fx.work, "main");
        commit_file(&fx.work, "one.txt", "feat: one");
        let one = commit_id(&fx.work, "@-");
        jj_ok(&fx.work, &["bookmark", "create", "line", "-r", &one]);
        jj_ok(&fx.work, &["new", &base]);
        commit_file(&fx.work, "side.txt", "feat: side");
        let side = commit_id(&fx.work, "@-");

        for to in [&base, &side] {
            let err = move_bookmark(&mut test_ctx(), &params(&fx, "line", to)).unwrap_err();
            assert!(err.to_string().contains("--allow-backwards"), "{err}");
            assert_eq!(commit_id(&fx.work, "line"), one);
        }
        let mut back = params(&fx, "line", &side);
        back.allow_backwards = true;
        move_bookmark(&mut test_ctx(), &back).expect("sideways, with the flag");
        assert_eq!(commit_id(&fx.work, "line"), side);
    }

    /// A bookmark that does not exist, a target of no commit or of
    /// several, are refused, and a dry run moves nothing.
    #[test]
    fn refusals_and_a_dry_run_change_nothing() {
        let fx = Fixture::new("mvbm-refused");
        jj_ok(&fx.work, &["bookmark", "create", "line", "-r", "main"]);
        commit_file(&fx.work, "one.txt", "feat: one");
        let at = commit_id(&fx.work, "line");

        let err = move_bookmark(&mut test_ctx(), &params(&fx, "absent", "@-")).unwrap_err();
        assert!(err.to_string().contains("creates none"), "{err}");
        for to in ["none()", "@- | @"] {
            let err = move_bookmark(&mut test_ctx(), &params(&fx, "line", to)).unwrap_err();
            assert!(err.to_string().contains("exactly one"), "{to}: {err}");
        }
        let mut dry = params(&fx, "line", "@-");
        dry.dry_run = true;
        move_bookmark(&mut test_ctx(), &dry).expect("dry run");
        assert_eq!(commit_id(&fx.work, "line"), at);
    }
}

