            short(&mv.to),
            mv.repo.display()
        );
        if params.dry_run {
            continue;
        }
        let snapshot = Snapshot::take(&mv.repo)?;
        if let Err(e) = ctx.session(&mv.repo)?.bookmark_set(name, &mv.to) {
            for s in moved.iter().rev() {
                s.restore("move-bookmark", e.as_ref());
            }
            return Err(e);
        }
        moved.push(snapshot);
    }
    Ok(())
}

